mkdir -p src/lib/email && cat > .env.example <<'EOF'
# Transactional email (Resend — https://resend.com)
# Leave RESEND_API_KEY empty in local dev to log emails to the console instead of sending.
RESEND_API_KEY=re_xxxxxxxxxxxxxxxxxxxxxxxx
# Must be on a domain verified in Resend.
EMAIL_FROM="Notely <hello@notely.example.com>"
EMAIL_REPLY_TO=support@notely.example.com

# Public base URL, used to build links in emails (e.g. password reset).
APP_URL=http://localhost:3000
EOF
cat > src/lib/email/send.ts <<'EOF'
import { Resend } from "resend";

export type EmailMessage = {
  to: string;
  subject: string;
  html: string;
  text: string;
  // Lets Resend dedupe retries of the same logical email.
  idempotencyKey?: string;
};

let client: Resend | undefined;

function getClient(): Resend | undefined {
  const apiKey = process.env.RESEND_API_KEY;
  if (!apiKey) return undefined;
  client ??= new Resend(apiKey);
  return client;
}

export async function sendEmail(message: EmailMessage): Promise<void> {
  const resend = getClient();

  if (!resend) {
    if (process.env.NODE_ENV === "production") {
      throw new Error("RESEND_API_KEY is not set");
    }
    // Local dev without credentials: print instead of sending.
    console.info(`[email] to=${message.to} subject="${message.subject}"\n${message.text}`);
    return;
  }

  const from = process.env.EMAIL_FROM;
  if (!from) throw new Error("EMAIL_FROM is not set");

  const { error } = await resend.emails.send(
    {
      from,
      to: message.to,
      replyTo: process.env.EMAIL_REPLY_TO || undefined,
      subject: message.subject,
      html: message.html,
      text: message.text,
    },
    message.idempotencyKey ? { idempotencyKey: message.idempotencyKey } : undefined,
  );

  if (error) {
    throw new Error(`Failed to send email "${message.subject}": ${error.name}: ${error.message}`);
  }
}
EOF
cat > src/lib/email/templates.ts <<'EOF'
type RenderedEmail = { subject: string; html: string; text: string };

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function layout(body: string): string {
  return `<!doctype html>
<html>
  <body style="margin:0;padding:24px;background:#f6f6f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#111;">
    <div style="max-width:480px;margin:0 auto;background:#fff;border-radius:8px;padding:32px;">
      ${body}
      <p style="margin-top:32px;font-size:12px;color:#888;">Notely</p>
    </div>
  </body>
</html>`;
}

function button(href: string, label: string): string {
  return `<a href="${escapeHtml(href)}" style="display:inline-block;padding:12px 20px;background:#111;color:#fff;text-decoration:none;border-radius:6px;">${escapeHtml(label)}</a>`;
}

export function welcomeEmail({ name, appUrl }: { name: string; appUrl: string }): RenderedEmail {
  const dashboardUrl = `${appUrl}/dashboard`;
  return {
    subject: "Welcome to Notely",
    html: layout(`
      <h1 style="font-size:20px;margin:0 0 16px;">Welcome, ${escapeHtml(name)}!</h1>
      <p>Your Notely account is ready. Jump in and write your first note.</p>
      <p style="margin:24px 0;">${button(dashboardUrl, "Open Notely")}</p>
    `),
    text: `Welcome, ${name}!\n\nYour Notely account is ready. Jump in and write your first note:\n${dashboardUrl}\n\n— Notely`,
  };
}

export function passwordResetEmail({
  name,
  resetUrl,
  expiresInMinutes,
}: {
  name: string;
  resetUrl: string;
  expiresInMinutes: number;
}): RenderedEmail {
  return {
    subject: "Reset your Notely password",
    html: layout(`
      <h1 style="font-size:20px;margin:0 0 16px;">Reset your password</h1>
      <p>Hi ${escapeHtml(name)}, we received a request to reset your Notely password.</p>
      <p style="margin:24px 0;">${button(resetUrl, "Choose a new password")}</p>
      <p style="font-size:14px;color:#555;">This link expires in ${expiresInMinutes} minutes. If you didn't ask for a reset, you can ignore this email — your password won't change.</p>
    `),
    text: `Hi ${name},\n\nWe received a request to reset your Notely password. Choose a new one here:\n${resetUrl}\n\nThis link expires in ${expiresInMinutes} minutes. If you didn't ask for a reset, ignore this email — your password won't change.\n\n— Notely`,
  };
}
EOF
cat > src/lib/email/index.ts <<'EOF'
import { sendEmail } from "./send";
import { passwordResetEmail, welcomeEmail } from "./templates";

function appUrl(): string {
  return (process.env.APP_URL ?? "http://localhost:3000").replace(/\/+$/, "");
}

export async function sendWelcomeEmail(user: { id: string; email: string; name: string }): Promise<void> {
  await sendEmail({
    to: user.email,
    ...welcomeEmail({ name: user.name, appUrl: appUrl() }),
    idempotencyKey: `welcome/${user.id}`,
  });
}

export async function sendPasswordResetEmail(
  user: { email: string; name: string },
  token: string,
  expiresInMinutes: number,
): Promise<void> {
  const resetUrl = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  await sendEmail({
    to: user.email,
    ...passwordResetEmail({ name: user.name, resetUrl, expiresInMinutes }),
  });
}
EOF

